"""Pinned read-only native checkout exporter. No network operations or imports of product code."""
import argparse
import base64
import configparser
import hashlib
import io
import json
import os
from pathlib import Path
import re
import resource
import ctypes
import errno
import shutil
import stat
import subprocess
import tarfile
import tempfile
from functools import partial
import zlib

REPOSITORY = 'idanilovqa/AlbumHaven'
SOURCE = 'd2777b7f827916f6ff458e987a232b754448928c'
TREE = 'ae78f6ac10b9c725331dc3f3174cc57980c23afa'
PARENT = '278ad75b3e7a30153e680ab01afaddefe4fe1832'
BRANCH = '2026-09-30-mobile-bundle-transfer'
WORKFLOW = '.github/workflows/verified-friends-checkout-export.yml'
PRODUCER_PATH = '.github/scripts/verified-friends-checkout-export.py'
SCHEMA = 'friends-native-checkout-v1'
MIB = 1024 * 1024
LIMITS = {'zip': 128*MIB, 'tar': 120*MIB, 'proof': 4*MIB,
          'outer_expanded': 124*MIB, 'member': 64*MIB,
          'object_store': 64*MIB, 'object_raw': 64*MIB,
          'inner_expanded': 112*MIB, 'members': 10000, 'scratch': 384*MIB,
          'git_memory': 512*MIB, 'git_seconds': 60, 'import_seconds': 480}
SAFE_CONFIG = (b'[core]\n\trepositoryformatversion = 0\n\tfilemode = true\n'
               b'\tbare = false\n\tlogallrefupdates = false\n')
# Bound separately to the complete, previously Editor-verified tree receipt.
PINNED_B64 = ''
PINNED_SHA256 = 'c94166d82c6cb710dbb1cf9c3727cad8be8c25bf682e1fadce4f32312b1013e3'
HEX40 = re.compile(r'[0-9a-f]{40}')
HEX64 = re.compile(r'[0-9a-f]{64}')


class GuardError(Exception):
    """A fail-closed contract rejection; messages never contain source bytes or secrets."""


def require(ok, code):
    if not ok:
        raise GuardError(code)


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def git_hash(kind, data):
    return hashlib.sha1(kind.encode()+b' '+str(len(data)).encode()+b'\0'+data).hexdigest()


def canonical(value):
    return (json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True)+'\n').encode()


def strict_json(raw):
    def unique(pairs):
        out = {}
        for key, value in pairs:
            require(key not in out, 'duplicate-json-key')
            out[key] = value
        return out
    try:
        return json.loads(raw, object_pairs_hook=unique,
                          parse_constant=lambda value: (_ for _ in ()).throw(GuardError('json-constant')))
    except (ValueError, UnicodeError, RecursionError):
        raise GuardError('invalid-json') from None


def safe_path(name):
    require(isinstance(name, str) and 0 < len(name.encode('utf-8')) <= 240, 'path-length')
    require(all(32 <= ord(c) < 127 for c in name), 'path-encoding')
    require('\\' not in name and ':' not in name and not name.startswith('/'), 'unsafe-path')
    parts = name.split('/')
    require(all(p not in ('', '.', '..') and not p.endswith(('.', ' ')) for p in parts), 'unsafe-path')
    require(all(p.lower() != '.git' for p in parts), 'git-path-alias')
    return name


def regular_bytes(path, limit=LIMITS['member']):
    # O_NOFOLLOW and link count also reject a source path swapped to an external inode.
    before_open = Path(path).lstat()
    require(stat.S_ISREG(before_open.st_mode) and before_open.st_nlink == 1, 'not-single-regular-file')
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        info = os.fstat(fd)
        require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1, 'not-single-regular-file')
        require(0 <= info.st_size <= limit, 'file-size')
        with os.fdopen(fd, 'rb', closefd=False) as stream:
            data = stream.read(limit+1)
        require(len(data) == info.st_size and len(data) <= limit, 'file-changed-or-large')
        after = os.fstat(fd)
        require((info.st_size, info.st_mtime_ns, info.st_ctime_ns) ==
                (after.st_size, after.st_mtime_ns, after.st_ctime_ns), 'file-changed')
        return data
    finally:
        os.close(fd)


def safe_root(path):
    path = Path(path).absolute()
    for item in [path, *path.parents]:
        require(not item.is_symlink(), 'symlink-root')
    require(path.is_dir(), 'missing-root')
    return path


def walk_regular(root):
    """Return all regular files; reject aliases and special filesystem nodes."""
    root = safe_root(root)
    files = {}
    directories = []
    for current, dirs, names in os.walk(root, followlinks=False):
        for name in dirs:
            path = Path(current)/name
            require(stat.S_ISDIR(path.lstat().st_mode), 'non-directory')
            directories.append(path.relative_to(root).as_posix())
        for name in names:
            path = Path(current)/name
            info = path.lstat()
            require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1, 'non-regular-node')
            files[path.relative_to(root).as_posix()] = path
        require(len(files)+len(directories) <= LIMITS['members'], 'filesystem-member-count')
    return files, directories


def git_env():
    return {'PATH': '/usr/bin:/bin', 'HOME': '/nonexistent', 'LANG': 'C', 'LC_ALL': 'C',
            'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': '/dev/null',
            'GIT_CONFIG_SYSTEM': '/dev/null', 'GIT_TERMINAL_PROMPT': '0',
            'GIT_ALLOW_PROTOCOL': '', 'GIT_PROTOCOL_FROM_USER': '0',
            'GIT_NO_LAZY_FETCH': '1', 'GIT_NO_REPLACE_OBJECTS': '1',
            'GIT_OPTIONAL_LOCKS': '0'}


def git_child_limits(output_limit):
    """Run only as the Git child's pre-exec function, never in the caller."""
    ceiling = max(output_limit, MIB)+1
    resource.setrlimit(resource.RLIMIT_FSIZE, (ceiling, ceiling))
    resource.setrlimit(resource.RLIMIT_AS, (LIMITS['git_memory'], LIMITS['git_memory']))
    resource.setrlimit(resource.RLIMIT_CPU, (LIMITS['git_seconds'], LIMITS['git_seconds']))


def git(repo, *args, limit=4*MIB):
    command = ['/usr/bin/git', '--no-pager', '-c', 'protocol.allow=never',
               '-c', 'core.hooksPath=/dev/null', '-c', 'core.fsmonitor=false',
               '-c', 'core.untrackedCache=false', '-c', 'gc.auto=0',
               '-c', 'credential.helper=', '-c', 'core.attributesFile=/dev/null',
               '-C', str(repo), *args]
    # Bounded files avoid unbounded subprocess PIPE memory. Never expose stderr.
    with tempfile.TemporaryFile() as out, tempfile.TemporaryFile() as err:
        try:
            done = subprocess.run(command, env=git_env(), stdin=subprocess.DEVNULL,
                                  stdout=out, stderr=err, timeout=LIMITS['git_seconds'], check=False, preexec_fn=partial(git_child_limits, limit))
        except (OSError, subprocess.SubprocessError):
            raise GuardError('git-unavailable-or-timeout') from None
        require(done.returncode == 0, 'git-command-failed')
        require(out.tell() <= limit and err.tell() <= MIB, 'git-output-limit')
        out.seek(0)
        return out.read(limit+1)


def validate_config(repo, imported=False):
    raw = regular_bytes(repo/'.git/config', 16384)
    if imported:
        require(raw == SAFE_CONFIG, 'imported-config-not-exact')
        return
    try:
        parser = configparser.RawConfigParser(strict=True, interpolation=None)
        parser.read_string(raw.decode('ascii'))
    except (configparser.Error, UnicodeError):
        raise GuardError('native-config-invalid') from None
    require(not parser.defaults(), 'config-defaults')
    require(set(parser.sections()) <= {'core', 'gc', 'remote "origin"', 'http "https://github.com/"'}, 'native-config-section')
    core = dict(parser.items('core')) if parser.has_section('core') else {}
    require(core.get('repositoryformatversion') == '0' and core.get('bare') == 'false'
            and core.get('filemode') == 'true', 'native-core-settings')
    require(set(core) <= {'repositoryformatversion', 'bare', 'filemode', 'logallrefupdates'},
            'native-config-key')
    require(core.get('logallrefupdates', 'true') == 'true', 'native-reflog-setting')
    if parser.has_section('gc'):
        require(dict(parser.items('gc')) == {'auto': '0'}, 'native-gc-setting')
    if parser.has_section('http "https://github.com/"'):
        require(not dict(parser.items('http "https://github.com/"')), 'native-http-setting')
    if parser.has_section('remote "origin"'):
        remote = dict(parser.items('remote "origin"'))
        require(remote == {'url': 'https://github.com/'+REPOSITORY,
                           'fetch': '+refs/heads/*:refs/remotes/origin/*'} or
                remote == {'url': 'https://github.com/'+REPOSITORY+'.git',
                           'fetch': '+refs/heads/*:refs/remotes/origin/*'}, 'native-remote-setting')


def validate_tree_manifest(manifest):
    require(set(manifest) == {'repository', 'commit', 'tree', 'entries'}, 'manifest-keys')
    require(manifest['repository'] == REPOSITORY and manifest['commit'] == SOURCE
            and manifest['tree'] == TREE, 'manifest-pins')
    entries = manifest['entries']
    require(isinstance(entries, list) and 0 < len(entries) <= LIMITS['members'], 'manifest-count')
    paths = set()
    leaves = {}
    trees = {'': TREE}
    for row in entries:
        require(isinstance(row, dict), 'manifest-row')
        path = safe_path(row.get('path'))
        require(path not in paths, 'manifest-duplicate')
        paths.add(path)
        require(isinstance(row.get('sha'), str) and HEX40.fullmatch(row['sha']), 'manifest-oid')
        if row.get('type') == 'tree':
            require(set(row) == {'path', 'mode', 'type', 'sha'} and row['mode'] == '040000',
                    'manifest-tree')
            trees[path] = row['sha']
        else:
            require(set(row) == {'path', 'mode', 'type', 'sha', 'size'}
                    and row['type'] == 'blob' and row['mode'] in ('100644', '100755')
                    and type(row['size']) is int and 0 <= row['size'] <= LIMITS['member'], 'manifest-blob')
            leaves[path] = row
    require(all(row['path'].rpartition('/')[0] in trees for row in entries), 'manifest-orphan')
    # Recompute every tree hash from the independent full path/mode/blob manifest.
    for path, oid in trees.items():
        children = []
        for row in entries:
            parent, _, name = row['path'].rpartition('/')
            if parent == path:
                sort_name = name.encode()+ (b'/' if row['type'] == 'tree' else b'')
                children.append((sort_name, row['mode'].lstrip('0').encode()+b' '+name.encode()+
                                 b'\0'+bytes.fromhex(row['sha'])))
        require(git_hash('tree', b''.join(data for _, data in sorted(children))) == oid, 'manifest-tree-hash')
    return leaves, trees


def pinned_manifest():
    raw = zlib.decompress(base64.b64decode(PINNED_B64, validate=True))
    require(sha256(raw) == PINNED_SHA256, 'embedded-manifest-hash')
    manifest = strict_json(raw)
    leaves, trees = validate_tree_manifest(manifest)
    require(len(leaves) == 2123 and len(trees) == 140
            and sum(r['size'] for r in leaves.values()) == 45853678, 'manifest-totals')
    return manifest


def validate_event(env, event):
    required = {'GITHUB_REPOSITORY': REPOSITORY, 'GITHUB_REF': 'refs/heads/'+BRANCH,
                'GITHUB_EVENT_NAME': 'push', 'GITHUB_RUN_ATTEMPT': '1'}
    require(all(env.get(k) == v for k, v in required.items()), 'event-context')
    require(isinstance(env.get('GITHUB_SHA'), str) and HEX40.fullmatch(env['GITHUB_SHA'])
            and env['GITHUB_SHA'] != PARENT, 'trigger-sha')
    require(re.fullmatch(r'[1-9][0-9]{0,19}', env.get('GITHUB_RUN_ID', '')), 'run-id')
    require(isinstance(event, dict) and event.get('before') == PARENT
            and event.get('after') == env['GITHUB_SHA']
            and event.get('ref') == 'refs/heads/'+BRANCH
            and event.get('deleted') is False and event.get('forced') is False
            and event.get('created') is False
            and event.get('repository', {}).get('full_name') == REPOSITORY, 'event-payload')
    require(env.get('GITHUB_WORKFLOW_REF') == REPOSITORY+'/'+WORKFLOW+'@refs/heads/'+BRANCH
            and env.get('GITHUB_WORKFLOW_SHA') == env['GITHUB_SHA'], 'workflow-context')
    return {'repository': REPOSITORY, 'helper_parent': PARENT,
            'helper_head': env['GITHUB_SHA'], 'helper_branch': BRANCH,
            'event': 'push', 'run_id': int(env['GITHUB_RUN_ID']), 'attempt': 1,
            'workflow_path': WORKFLOW}


def validate_control(control, env):
    control = safe_root(control)
    require((control/'.git').is_dir() and not (control/'.git').is_symlink(), 'control-git-dir')
    validate_config(control)
    require(git(control, 'rev-parse', 'HEAD').strip().decode() == env['GITHUB_SHA'], 'control-head')
    raw = git(control, 'cat-file', 'commit', env['GITHUB_SHA'])
    parents = [line[7:].decode() for line in raw.split(b'\n\n', 1)[0].splitlines() if line.startswith(b'parent ')]
    require(parents == [PARENT], 'control-parent')
    delta = git(control, 'diff-tree', '--no-commit-id', '--name-status', '-r', '-z', PARENT, env['GITHUB_SHA'])
    expected_delta = b''.join(b'A\0'+path.encode()+b'\0' for path in sorted((WORKFLOW, PRODUCER_PATH)))
    require(delta == expected_delta, 'control-delta')
    require(git(control, 'ls-tree', PARENT, '--', WORKFLOW) == b'', 'workflow-already-present')
    workflow = regular_bytes(control/WORKFLOW, MIB)
    row = git(control, 'ls-tree', '-z', 'HEAD', '--', WORKFLOW)
    require(row == b'100644 blob '+git_hash('blob', workflow).encode()+b'\t'+WORKFLOW.encode()+b'\0',
            'workflow-bytes-or-mode')
    producer = regular_bytes(control/PRODUCER_PATH, MIB)
    require(git(control, 'ls-tree', PARENT, '--', PRODUCER_PATH) == b'', 'producer-already-present')
    row = git(control, 'ls-tree', '-z', 'HEAD', '--', PRODUCER_PATH)
    require(row == b'100644 blob '+git_hash('blob', producer).encode()+b'\t'+PRODUCER_PATH.encode()+b'\0',
            'producer-bytes-or-mode')
    require(sha256(producer) == env.get('FRIENDS_PRODUCER_SHA256')
            and git_hash('blob', producer) == env.get('FRIENDS_PRODUCER_BLOB'), 'producer-pin')
    return sha256(workflow)


def object_files(repo):
    objects = repo/'.git/objects'
    files, directories = walk_regular(objects)
    allowed_dirs = {'info', 'pack'} | {f'{x:02x}' for x in range(256)}
    require(set(directories) <= allowed_dirs, 'object-directory')
    total = 0
    packs = set()
    indexes = set()
    for name, path in files.items():
        safe_path(name)
        info = path.lstat()
        require(info.st_size <= LIMITS['member'], 'object-member-size')
        total += info.st_size
        if re.fullmatch(r'[0-9a-f]{2}/[0-9a-f]{38}', name):
            continue
        match = re.fullmatch(r'pack/(pack-[0-9a-f]{40})\.(pack|idx)', name)
        require(match is not None, 'forbidden-object-file')
        (packs if match[2] == 'pack' else indexes).add(match[1])
    require(packs == indexes and total <= LIMITS['object_store'], 'object-store-bounds')
    return files


def validate_native(repo, imported=False):
    repo = safe_root(repo)
    gitdir = repo/'.git'
    require(gitdir.is_dir() and not gitdir.is_symlink(), 'native-git-dir')
    validate_config(repo, imported)
    walk_regular(gitdir)
    require(not os.path.lexists(gitdir/'packed-refs'), 'packed-refs-not-supported')
    refs, _ = walk_regular(gitdir/'refs')
    require(all(regular_bytes(path, 64) == (SOURCE+'\n').encode() for path in refs.values()),
            'native-ref-outside-source')
    # Neither a .git file nor any alternate repository discovery path is allowed.
    for name in ('commondir', 'gitdir', 'worktrees', 'config.worktree', 'info/grafts', 'refs/replace'):
        require(not os.path.lexists(gitdir/name), 'forbidden-native-metadata')
    head = regular_bytes(gitdir/'HEAD', 64)
    shallow = regular_bytes(gitdir/'shallow', 64)
    require(head == (SOURCE+'\n').encode(), 'native-detached-head')
    require(shallow == head, 'native-shallow-boundary')
    objects = object_files(repo)
    require(git(repo, 'rev-parse', '--is-shallow-repository') == b'true\n', 'native-not-shallow')
    require(git(repo, 'rev-parse', 'HEAD^{commit}') == head
            and git(repo, 'rev-parse', 'HEAD^{tree}').strip().decode() == TREE, 'native-pins')
    leaves, trees = validate_tree_manifest(pinned_manifest())
    expected = {SOURCE: 'commit'}
    expected.update({oid: 'tree' for oid in trees.values()})
    expected.update({row['sha']: 'blob' for row in leaves.values()})
    inventory = []
    seen = set()
    total_raw = 0
    rows = git(repo, 'cat-file', '--batch-all-objects', '--batch-check=%(objectname) %(objecttype) %(objectsize)').splitlines()
    require(len(rows) == len(expected), 'native-object-count')
    for line in rows:
        fields = line.decode('ascii').split(' ')
        require(len(fields) == 3 and fields[2].isdigit(), 'native-object-row')
        oid, kind, size_text = fields
        size = int(size_text)
        require(oid in expected and expected[oid] == kind and oid not in seen, 'native-object-scope')
        require(size <= LIMITS['member'], 'native-object-size')
        total_raw += size
        require(total_raw <= LIMITS['object_raw'], 'native-object-total')
        data = git(repo, 'cat-file', kind, oid, limit=LIMITS['member'])
        require(len(data) == size and git_hash(kind, data) == oid, 'native-object-hash')
        inventory.append({'oid': oid, 'type': kind, 'size': size, 'sha256': sha256(data)})
        seen.add(oid)
    require(seen == set(expected), 'native-object-closure')
    git(repo, 'fsck', '--full', '--strict', '--no-reflogs', '--no-dangling', SOURCE)
    listing = git(repo, 'ls-tree', '-r', '-z', '--full-tree', SOURCE)
    expected_listing = b''.join(row['mode'].encode()+b' blob '+row['sha'].encode()+b'\t'+path.encode()+b'\0'
                                for path, row in sorted(leaves.items()))
    require(listing == expected_listing, 'native-tree-listing')
    # All source worktree files must be tracked; ignore only the native .git directory.
    workfiles = {}
    workdirs = []
    for current, dirs, names in os.walk(repo, followlinks=False):
        if Path(current) == repo:
            dirs.remove('.git')
        for name in dirs:
            path = Path(current)/name
            require(stat.S_ISDIR(path.lstat().st_mode), 'worktree-symlink-directory')
            workdirs.append(path.relative_to(repo).as_posix())
        for name in names:
            path = Path(current)/name
            relative = path.relative_to(repo).as_posix()
            safe_path(relative)
            require(relative not in workfiles, 'duplicate-worktree-path')
            workfiles[relative] = path
        require(len(workfiles)+len(workdirs) <= LIMITS['members'], 'worktree-member-count')
    require(set(workfiles) == set(leaves) and set(workdirs) == set(trees)-{''}, 'native-worktree-scope')
    file_inventory = []
    for path, row in sorted(leaves.items()):
        data = regular_bytes(workfiles[path])
        mode = stat.S_IMODE(workfiles[path].stat().st_mode)
        wanted = 0o755 if row['mode'] == '100755' else 0o644
        require(mode == wanted and len(data) == row['size'] and git_hash('blob', data) == row['sha'],
                'native-worktree-bytes-or-mode')
        file_inventory.append({'path': path, 'mode': row['mode'], 'blob': row['sha'],
                               'size': len(data), 'sha256': sha256(data)})
    # Direct path/byte/mode checks above establish worktree equality without using
    # a worktree diff, which can write the index even with GIT_OPTIONAL_LOCKS=0.
    require(git(repo, 'diff', '--cached', '--no-ext-diff', '--no-textconv', '--raw', 'HEAD', '--') == b'',
            'native-dirty-index')
    return {'head': head, 'shallow': shallow, 'objects': objects,
            'object_inventory': sorted(inventory, key=lambda row: row['oid']), 'files': file_inventory}


def add_tar_bytes(archive, name, data, mode):
    safe_path(name)
    info = tarfile.TarInfo(name)
    info.size = len(data)
    info.mode = mode
    info.uid = info.gid = info.mtime = 0
    info.uname = info.gname = ''
    archive.addfile(info, io.BytesIO(data))


def rename_noreplace(source, destination):
    """Linux atomic publish; never overwrite even an empty existing destination."""
    libc = ctypes.CDLL(None, use_errno=True)
    function = getattr(libc, 'renameat2', None)
    require(function is not None, 'atomic-rename-unavailable')
    function.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    function.restype = ctypes.c_int
    result = function(-100, os.fsencode(source), -100, os.fsencode(destination), 1)
    if result != 0:
        if ctypes.get_errno() == errno.EEXIST:
            raise GuardError('destination-exists')
        raise GuardError('atomic-rename-failed')


def produce(control, source, out, env):
    control, source = safe_root(control), safe_root(source)
    require(control != source and control not in source.parents and source not in control.parents,
            'checkout-overlap')
    event = strict_json(regular_bytes(Path(env['GITHUB_EVENT_PATH']), MIB))
    identity = validate_event(env, event)
    workflow_hash = validate_control(control, env)
    native = validate_native(source)
    out = Path(out).absolute()
    parent = safe_root(out.parent)
    require(not os.path.lexists(out), 'output-exists')
    require(source not in out.parents and control not in out.parents, 'output-in-checkout')
    stage = Path(tempfile.mkdtemp(prefix='.friends-export-', dir=parent))
    try:
        members = []
        total = 0
        with tarfile.open(stage/'checkout.tar', 'x', format=tarfile.USTAR_FORMAT) as archive:
            # Refs is an authentic directory, never a fabricated branch/ref value.
            require((source/'.git/refs').is_dir() and not (source/'.git/refs').is_symlink(), 'native-refs-directory')
            for name in ('git/refs',):
                info = tarfile.TarInfo(name)
                info.type, info.mode = tarfile.DIRTYPE, 0o755
                info.uid = info.gid = info.mtime = 0
                archive.addfile(info)
                members.append({'path': name, 'type': 'directory', 'mode': 0o755, 'size': 0, 'sha256': sha256(b'')})
            rows = [('git/HEAD', native['head'], 0o644), ('git/shallow', native['shallow'], 0o644),
                    ('git/config', SAFE_CONFIG, 0o644)]
            for name, path in sorted(native['objects'].items()):
                rows.append(('git/objects/'+name, regular_bytes(path), 0o644))
            for row in native['files']:
                data = regular_bytes(source/row['path'])
                require(sha256(data) == row['sha256'], 'worktree-changed-before-package')
                rows.append(('worktree/'+row['path'], data, int(row['mode'][-3:], 8)))
            for name, data, mode in rows:
                total += len(data)
                require(total <= LIMITS['inner_expanded'], 'tar-expanded-limit')
                add_tar_bytes(archive, name, data, mode)
                members.append({'path': name, 'type': 'file', 'mode': mode, 'size': len(data), 'sha256': sha256(data)})
            require(len(members) <= LIMITS['members'], 'tar-member-count')
        tar_bytes = regular_bytes(stage/'checkout.tar', LIMITS['tar'])
        proof = {'schema': SCHEMA, **identity, 'source_commit': SOURCE, 'source_tree': TREE,
                 'workflow_sha256': workflow_hash, 'producer_path': PRODUCER_PATH,
                 'producer_sha256': env['FRIENDS_PRODUCER_SHA256'],
                 'producer_blob': env['FRIENDS_PRODUCER_BLOB'], 'limits': LIMITS,
                 'shallow': [SOURCE], 'files': native['files'], 'objects': native['object_inventory'],
                 'members': members, 'inner_bytes': total,
                 'tar_size': len(tar_bytes), 'tar_sha256': sha256(tar_bytes),
                 'git_version': git(source, '--version').decode('ascii').strip(),
                 'sanitization': 'allowlisted-only-no-auth-remotes-hooks-logs-or-environment'}
        raw = canonical(proof)
        require(len(raw) <= LIMITS['proof'] and len(raw)+len(tar_bytes) <= LIMITS['outer_expanded'], 'proof-or-outer-limit')
        (stage/'proof.json').write_bytes(raw)
        # Revalidate after serialization. A moving checkout is rejected, never repaired.
        after = validate_native(source)
        require(after['object_inventory'] == native['object_inventory'] and after['files'] == native['files'],
                'source-changed-during-export')
        require(validate_control(control, env) == workflow_hash, 'control-changed-during-export')
        require(not os.path.lexists(out), 'output-created-during-export')
        # The runner has sole ownership of this random export path; no existing output is replaced.
        rename_noreplace(stage, out)
        return proof
    finally:
        if stage.exists():
            shutil.rmtree(stage)


def main():
    parser = argparse.ArgumentParser(description='Export the exact admitted Friends native checkout')
    parser.add_argument('--control', required=True, type=Path)
    parser.add_argument('--source', required=True, type=Path)
    parser.add_argument('--out', required=True, type=Path)
    args = parser.parse_args()
    try:
        require(sha256(regular_bytes(Path(__file__), MIB)) == os.environ.get('FRIENDS_PRODUCER_SHA256'),
                'running-producer-pin')
        produce(args.control, args.source, args.out, os.environ)
    except (GuardError, OSError, ValueError, KeyError, tarfile.TarError):
        # Never echo attacker-controlled input, command output, paths, or credentials.
        raise SystemExit('Native checkout export rejected; no artifact is admitted') from None
    print('Pinned native checkout exported with sanitized metadata')


if __name__ == '__main__':
    main()
